fn frame(t: i32) {
    host::display::clear(0x000010);
    let w: i32 = host::display::width();
    let cy: i32 = host::display::height() / 2;
    let msg = [82, 85, 83, 84, 76, 73, 84, 69, 32, 82, 79, 67, 75, 83];
    let n: i32 = 14;
    let span: i32 = n * 26 + w;
    let head: i32 = w - (t * 3) % span;
    let mut i: i32 = 0;
    while i < n {
        let x: i32 = head + i * 26;
        let y: i32 = cy + (50 * host::math::sin(x * 2 + t * 2)) / 256;
        host::display::draw_char(x, y, msg[i], 0x66ffee, 3);
        i = i + 1;
    }
    host::display::present();
}
